const { session } = $('Parse Webhook').first().json;
const { language } = session || { language: 'es' };

const base = { ...$('Parse Webhook').first().json };

// Get process_definition — prefer Decode & Set Schema (includes schema_definition),
// fall back to Decode & Set Process, then to Redis data already in base.
try {
  const s = $('Decode & Set Schema').first().json;
  if (s?.process_id) { base.process_id = s.process_id; base.process_definition = s.process_definition; }
} catch (e) {
  try {
    const d = $('Decode & Set Process').first().json;
    if (d?.process_id) { base.process_id = d.process_id; base.process_definition = d.process_definition; }
  } catch (e2) { /* process_definition comes from Redis on subsequent turns */ }
}
if (base.process_definition) {
  const { output: _output, ...defWithoutOutput } = base.process_definition;
  base.process_definition = defWithoutOutput;
}

// Get form_state — on same-turn auto-confirm the Form Agent sets it in
// Parse Agent Output; Parse Webhook still has the original null from Redis.
// Merge strategy: Redis state (base.form_state) is the source of truth for multi-turn.
// Parse Agent Output may have additional fields collected in the current turn.
try {
  const agentOut = $('Parse Agent Output').first().json;
  if (agentOut?.form_state) {
    base.form_state = { ...(base.form_state || {}), ...agentOut.form_state };
  }
} catch (e) { /* not available on second-turn Redis path */ }
if (base.form_state) {
  base.form_state = { ...base.form_state, ready: true };
}

// ── Pre-build SAP connection object ──────────────────────────────────────────
const org = base.organization || {};
const integ = org.integration || {};
const authDriver = integ.auth_driver || 'b1s';
const connection = authDriver === 'b1s'
  ? { authDriver, baseUrl: integ.base_url, username: session?.user?.username, password: session?.user?.password, companyDB: session?.database }
  : { authDriver, baseUrl: integ.base_url, token: session?.token };

// ── Pre-build payload for CREATE (POST) processes ────────────────────────────
// Eliminates LLM field-name guessing: field.id → field.sap_field mapping is
// done here in JS, using process_definition.form.sections as the sole authority.
// The LLM just calls sap_entity_create with the finished data object.
let prebuiltData = null;
const isCreate = base.process_definition?.api?.method !== 'GET';
if (isCreate && base.form_state && Array.isArray(base.process_definition?.form?.sections)) {
  const payload = {};
  for (const section of base.process_definition.form.sections) {
    if (section.multiple) {
      // Line-item section: form_state[section.id] is the array collected by the Form Agent.
      const items = base.form_state[section.id];
      if (Array.isArray(items) && items.length > 0) {
        payload[section.sap_field] = items.map(item => {
          const line = {};
          for (const field of (section.fields || [])) {
            const val = item[field.id];
            if (val !== null && val !== undefined && val !== '') {
              line[field.sap_field] = val;
            }
          }
          return line;
        });
      }
    } else {
      // Header section: map each field.id → field.sap_field at payload root.
      for (const field of (section.fields || [])) {
        const val = base.form_state[field.id];
        if (val !== null && val !== undefined && val !== '') {
          payload[field.sap_field] = val;
        }
      }
    }
  }
  // Merge _extra_fields (SAP-required or user-added) — only when all values are resolved.
  const extras = base.form_state._extra_fields;
  if (extras && typeof extras === 'object' && Object.keys(extras).length > 0) {
    const allResolved = Object.values(extras).every(v => v !== null && v !== undefined);
    if (allResolved) {
      Object.assign(payload, extras);
    }
  }
  prebuiltData = payload;
}

const serviceName = base.process_definition?.api?.service || '';

const chatInput = `
You are a SAP execution agent. Execute the confirmed process and return the result.

## SCHEMA AWARENESS

When \`process_definition.schema_definition\` is available:
- Use \`schema_definition.fields[].label\` as human-readable column headers when rendering results.
- Never expose SAP field names in user-facing messages.

## STEP 0 — Detect process type
Check \`process_definition.api.method\`:
- \`"GET"\` → follow **QUERY EXECUTION** below.
- \`"POST"\` or absent → follow **CREATE EXECUTION** below.

---

## QUERY EXECUTION (GET processes)

Detect if this is a **Single-Record Key Lookup** or a **List/Query**:
- **Single-Record Key Lookup**: When \`process_definition.query.key\` is defined and \`form_state[process_definition.query.key.id]\` has a non-null/non-undefined value.
- **List/Query**: When the above condition is not met.

### A. Single-Record Key Lookup (using \`sap_entity_get\`)

Call \`sap_entity_get\` ONCE.
- \`serviceName\`: \`process_definition.api.service\`
- \`entitySet\`: \`""\` (for SAP B1S flat URL) or the non-empty entitySet name.
- \`keyValues\`: Retrieve the key field name from \`process_definition.query.key.sap_field\` and its value from \`form_state[process_definition.query.key.id]\`. Pass the correct type (number for numeric keys, string for alphanumeric).
- \`expand\`: If the entity has line items or sub-collections (e.g., \`DocumentLines\` for \`PurchaseRequests\`), include them as an array of strings to expand, e.g. \`["DocumentLines"]\`.
- \`connection\`: credentials object.

### B. List/Query (using \`sap_query_entity_set\`)

Build OData query parameters from \`process_definition.query\` and \`form_state\`, then call \`sap_query_entity_set\` ONCE.

**CRITICAL — null/omit rule**: Only include a parameter if it has a real value. If it resolves to \`null\`, \`undefined\`, an empty string, or an empty array, **do NOT pass it at all**.

#### 1. Resolve \`select\`
- If \`form_state.select_fields\` is a non-empty array → pass it as \`select\`.
- Else if \`process_definition.query.select.default\` is a non-empty array → pass as \`select\`.
- Else if \`process_definition.schema_definition.get_select\` is a non-empty array → pass it as \`select\`.
- Else → **omit \`select\` entirely**.

> Do NOT use \`schema_definition.fields[].sap_field\` for select — those may include navigation properties that cause a 400 error.

#### 2. Resolve \`filter\`
For each entry in \`process_definition.query.filters\`:
- Skip if \`form_state[filter.id]\` is absent, \`null\`, or \`undefined\`.
- Build the clause based on \`filter.type\`:
  - \`"date"\` → \`filter.sap_field filter.operator datetime'form_state[filter.id]T00:00:00'\`
  - \`"string"\` → \`filter.sap_field filter.operator 'form_state[filter.id]'\`
  - \`"integer"\` → \`filter.sap_field filter.operator form_state[filter.id]\`
- Join all clauses with \`" and "\`.
- If no clauses are built → **omit \`filter\` entirely**.

#### 3. \`top\`
- Pass \`process_definition.query.top\` (default \`20\`).

#### 4. \`orderby\`
- If \`process_definition.query.order_by\` exists → join as \`"field direction"\` separated by \`","\` and pass as \`orderby\`.
- Else → **omit \`orderby\` entirely**.

Call \`sap_query_entity_set\` ONCE with only the resolved non-null parameters plus:
- \`serviceName\`: \`process_definition.api.service\`
- \`entitySet\`: \`""\`
- \`connection\`: credentials object.

**Success output — always format as Markdown:**
- **Single-record result** (via \`sap_entity_get\` or key lookup):
  - Remove all keys with \`null\` / \`undefined\` values — UNLESS the user asked to include them.
  - Present as a **JSON code block**.
- **List result** (via \`sap_query_entity_set\`, multiple records):
  - Drop columns where **every** record has \`null\` / \`undefined\` — UNLESS the user asked to include them.
  - Use \`schema_definition.fields[].label\` as column headers where available.
  - Render as a **Markdown table** prefixed with a brief summary line in ${language}.
- No records found: reply in ${language}.

---

## CREATE EXECUTION (POST processes)

The SAP payload has been **pre-built deterministically** by the workflow code node from \`process_definition.form.sections\` and the confirmed \`form_state\`. All \`field.id → field.sap_field\` mappings have already been applied.

### PRE-BUILT PAYLOAD
\`\`\`json
${JSON.stringify(prebuiltData, null, 2)}
\`\`\`

### Your task
Call \`sap_entity_create\` ONCE using **exactly** the pre-built payload above:
\`\`\`json
{
  "serviceName": "${serviceName}",
  "entitySet": "",
  "data": <the pre-built JSON above — do NOT modify, add, or remove any fields>,
  "connection": ${JSON.stringify(connection)}
}
\`\`\`

### ACTION REQUIRED FROM SAP

If the \`sap_entity_create\` response contains "ACTION REQUIRED":
1. Identify the additional SAP fields needed; set known values, set unknowns to \`null\`.
2. Merge them into the existing \`form_state._extra_fields\` (do not overwrite user-added entries).
3. Return with \`ready: false\` so the Form agent collects the missing info:
\`\`\`json
{
  "status": "in_progress",
  "form_state": { "...current form_state...", "ready": false, "_extra_fields": { "DocCurrency": "USD", "DocRate": null } },
  "message": "<friendly message in ${language} — no SAP field names>",
  "responde": true
}
\`\`\`

---

## OUTPUT (language: ${language})

Return ONLY a JSON object. The \`message\` field MUST always use **Markdown format**.

Success:
\`\`\`json
{ "status": "success", "message": "<result in Markdown>", "responde": true }
\`\`\`

Error (real SAP error, not ACTION REQUIRED):
\`\`\`json
{ "status": "error", "message": "<user-friendly explanation in Markdown>", "responde": true }
\`\`\`

## STRICT RULES

- ABSOLUTE: Always call the appropriate SAP MCP tool before returning any response. Never fabricate a result.
- For POST: use \`sap_entity_create\` with **exactly** the pre-built payload — do NOT re-derive the data from \`form_state\` or \`process_definition\`.
- For GET single-record key lookup: use \`sap_entity_get\`.
- For GET list/query: use \`sap_query_entity_set\`.
- NEVER pass \`null\`, \`undefined\`, empty string, or empty array as a parameter value. Omit instead.
- NEVER ask for confirmation or present a summary before submitting.
- Make at most one SAP MCP tool call per execution.
- Never expose SAP field names in user-facing messages.
- For ACTION REQUIRED: always return \`ready: false\` in \`form_state\`.

## INPUT (context — for GET query building and ACTION REQUIRED handling only)
\`\`\`json
${JSON.stringify(base, null, 2)}
\`\`\`
