return [{
  json: {
    chatInput,
  }
}];

const raw = $input.first().json.output;

let content;
try {
  const stripped = raw.replace(/^```json\n?/, '').replace(/\n?```$/, '').trim();
  content = JSON.parse(stripped);
} catch (e) {
  try {
    content = JSON.parse(raw.trim());
  } catch (e2) {
    return [{ json: { error: 'PARSE_ERROR', message: String(raw), responde: true } }];
  }
}

if (content.error) {
  return [{ json: { ...content } }];
}

// Unwrap if AI returned the entry nested under a key (e.g. {"1": {entry}})
if (!content.path) {
  const vals = Object.values(content);
  if (vals.length === 1 && vals[0]?.path) content = vals[0];
}

if (!content.path) {
  return [{ json: { error: 'PARSE_ERROR', message: 'Could not extract process path from agent response.', responde: true } }];
}

// content is a matched index entry with at least path and slug
const fullObj = $('Parse Webhook').first().json;
const ref = fullObj.github_tag || 'main';
const target = fullObj.organization?.target || '';
const orgSlug = fullObj.organization?.slug || '';
const owner = fullObj.github_owner;
const repo = fullObj.github_repo;
const pathSegs = content.path.split('/');
const filename = pathSegs[pathSegs.length - 1];
const module = content.module || pathSegs[pathSegs.length - 2] || '';
const pathPrefix = pathSegs[0] || '';

return [{
  json: {
    ...fullObj,
    matched_entry: content,
    standard_path: content.path,
    override_path: `${pathPrefix}/${orgSlug}/${module}/${filename}`,
    github_ref: ref,
    github_api_base: `https://api.github.com/repos/${owner}/${repo}/contents`,
    responde: false,
  }
}];

const fileData = $input.first().json;
const statusCode = fileData.statusCode;

if (fileData.error || (statusCode && statusCode >= 400)) {
  return [{ json: { error: 'NOT_FOUND', message: 'The process definition could not be loaded. Please try again.', responde: true } }];
}

const rawContent = (fileData.body || fileData).content;

let processDefinition;
try {
  const decoded = Buffer.from(rawContent.replace(/\n/g, ''), 'base64').toString('utf-8');
  processDefinition = JSON.parse(decoded);
} catch (e) {
  return [{ json: { error: 'NOT_FOUND', message: 'The process definition could not be parsed. Please try again.', responde: true } }];
}

const fullObj = { ...$('Parse Webhook').first().json };
fullObj['process_definition'] = processDefinition;
fullObj['process_id'] = processDefinition.id;

const filePath = (fileData.body || fileData).path || '';
const fileDir = filePath ? filePath.substring(0, filePath.lastIndexOf('/')) : '';
const owner = fullObj.github_owner || '';
const repo = fullObj.github_repo || '';
const githubRef = fullObj.github_tag || 'main';
const schemaSlug = processDefinition.schema || '';
fullObj['schema_fetch_url'] = (fileDir && schemaSlug && owner && repo)
  ? 'https://api.github.com/repos/' + owner + '/' + repo + '/contents/' + fileDir + '/' + schemaSlug + '.json?ref=' + githubRef
  : null;

return [{
  json: {
    ...fullObj,
    responde: false,
  }
}];

const raw = $input.first().json.output;

let content;
try {
  const stripped = raw.replace(/^```json\n?/, '').replace(/\n?```$/, '').trim();
  content = JSON.parse(stripped);
} catch (e) {
  try {
    content = JSON.parse(raw.trim());
  } catch (e2) {
    return [{ json: { error: 'PARSE_ERROR', message: raw, responde: true } }];
  }
}

// Build fullObj early so state is available for error preservation.
// Turn 1: process_id/process_definition come from Decode & Set Process.
// Turn 2+: they come from Redis via Parse Webhook.
const fullObj = (() => {
  const base = { ...$('Parse Webhook').first().json };
  try {
    const s = $('Decode & Set Schema').first().json;
    if (s?.process_id) {
      base.process_id = s.process_id;
      base.process_definition = s.process_definition;
    }
  } catch (e) {
    try {
      const d = $('Decode & Set Process').first().json;
      if (d?.process_id) {
        base.process_id = d.process_id;
        base.process_definition = d.process_definition;
      }
    } catch (e2) { /* not in this execution path — use webhook payload (loaded from Redis) */ }
  }
  return base;
})();

if (content.error) {
  // Preserve session state so the user doesn't lose in-progress work after an error.
  return [{ json: {
    ...content,
    form_state: content.form_state ?? fullObj.form_state ?? null,
    process_id: content.process_id ?? fullObj.process_id ?? null,
    process_definition: content.process_definition ?? fullObj.process_definition ?? null,
    processes: content.processes ?? fullObj.processes ?? null,
  } }];
}

// AI Agent Form / Execute response: has status + message fields.
if (content.status !== undefined) {
  if (content.status === 'confirmed') {
    // Merge with fullObj.form_state — the agent may return a partial or empty form_state.
    content.form_state = { ...(fullObj.form_state || {}), ...(content.form_state || {}), ready: true };
    content.responde = false;
  }
  if (['success', 'cancelled'].includes(content.status)) {
    content.form_state = null;
    content.process_id = null;
    content.process_definition = null;
  }
  if (content.status === 'error' && fullObj.form_state) {
    content.form_state = { ...fullObj.form_state, ready: false };
  }
  // Preserve ready=true only when the agent omitted it entirely.
  // If the agent explicitly returns ready: false (e.g. ACTION REQUIRED), respect that.
  if (content.status === 'in_progress' && content.form_state && content.form_state.ready === undefined) {
    if (fullObj.form_state?.ready === true) {
      content.form_state.ready = true;
    }
  }
  return [{ json: { ...fullObj, ...content } }];
}

return [{
  json: {
    ...fullObj,
    responde: false,
  },
}];

const body = $input.first().json.body;
return [{
  json: {
    ...body,
    github_owner: 'blasvicco',
    github_repo: 'da-sapot-processes',
    current_date: new Date().toISOString().split('T')[0],
  },
}];

const { message, session } = $('Parse Webhook').first().json;
const { language } = session || { language: 'es' };
const errorText = $json.error?.message || $json.error?.description || String($json.error || '');
const isRateLimit = /rate limit|tokens per min|TPM|too large/i.test(errorText);

const context = isRateLimit
  ? `This is a token rate-limit error. Tell the user (friendly, in ${language}) the search returned too many items and they should narrow it down — e.g., a more specific name, an item code, or a category.`
  : `Write a short friendly message in ${language} that something went wrong and they can try again or contact support. No technical jargon.`;

const chatInput = `
Error while processing a user request:

Error: ${errorText}
User message: ${message}

${context}

Respond with ONLY:
\`\`\`json
{ "error": "AGENT_ERROR", "message": "Your message to the user", "responde": true }
\`\`\`
`;

return [{
  json: {
    chatInput,
  }
}];

const payload = $input.first().json;
const { pending_processes, message } = payload;

if (!pending_processes || !pending_processes.length) {
  return [{ json: payload }];
}

const raw = (message || '').trim();

const numMatch   = raw.match(/^([1-9]\d*)$/);
const alphaMatch = raw.match(/^([a-zA-Z])$/);

let index = null;
if (numMatch)   index = parseInt(numMatch[1]) - 1;
if (alphaMatch) index = alphaMatch[1].toUpperCase().charCodeAt(0) - 65;

if (index === null || index < 0 || index >= pending_processes.length) {
  const opts = pending_processes
    .map((p, i) => `${i + 1}. ${p.display_name || p.name}`)
    .join('  ');
  return [{ json: {
    ...payload,
    message: `Por favor elige una opción válida:\n${opts}`,
    responde: true,
    processes: pending_processes,
  }}];
}

const resolved  = pending_processes[index];
const fullObj   = { ...$('Parse Webhook').first().json };
const ref       = fullObj.github_tag || 'main';
const orgSlug   = fullObj.organization?.slug || '';
const owner     = fullObj.github_owner;
const repo      = fullObj.github_repo;
const resolvedSegs = resolved.path.split('/');
const filename  = resolvedSegs[resolvedSegs.length - 1];
const module    = resolved.module || resolvedSegs[resolvedSegs.length - 2] || '';
const pathPrefix = resolvedSegs[0] || '';

return [{ json: {
  ...fullObj,
  matched_entry:     resolved,
  standard_path:     resolved.path,
  override_path:     `${pathPrefix}/${orgSlug}/${module}/${filename}`,
  github_ref:        ref,
  github_api_base:   `https://api.github.com/repos/${owner}/${repo}/contents`,
  pending_processes: null,
  processes:         null,
  selection_resolved: true,
  responde: false,
}}];

const fileData = $input.first().json;
const prevData = $('Decode & Set Process').first().json;

if (!prevData.schema_fetch_url || fileData.error || (fileData.statusCode && fileData.statusCode >= 400)) {
  return [{ json: { ...prevData, responde: false } }];
}

const rawContent = (fileData.body || fileData).content;
let schemaDefinition = null;
try {
  const decoded = Buffer.from(rawContent.replace(/\n/g, ''), 'base64').toString('utf-8');
  schemaDefinition = JSON.parse(decoded);
} catch (e) {
  return [{ json: { ...prevData, responde: false } }];
}

const output = { ...prevData };
if (output.process_definition && schemaDefinition) {
  output.process_definition = { ...output.process_definition, schema_definition: schemaDefinition };
}

return [{ json: { ...output, responde: false } }];
